mapper.select:
SELECT DISTINCT A.FINPROD_ID id,
A.FINPROD_ID text,
A.FINPROD_ID, A.FINPROD_NAME, A.FINPROD_ABBR, DATE_FORMAT(A.VDATE, '%Y-%m-%d') VDATE, DATE_FORMAT(A.MDATE, '%Y-%m-%d') MDATE, DATE_FORMAT(A.IDATE, '%Y-%m-%d') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, B.TYPE_6,
B.TYPE_9, B.TYPE_10, B.TYPE_11,
A.FINPROD_MARKET_ID, A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
LEFT JOIN TRD_PRODUCT_DEAL D ON A.FINPROD_ID = D.FINPROD_ID LEFT JOIN PTL_SEC_POSITION P ON P.FINPROD_ID = D.FINPROD_ID AND P.CDATE = D.TRADE_DATE
( A.FINPROD_MARKET_ID LIKE CONCAT_WS('', '%', #{search}, '%') or A.FINPROD_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
and P.PORTFOLIO_ID = #{portfolioId1} and p.AMOUNT != 0 AND p.INV_AIM != '999999'
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}

trim.if:
select total.totle_trade_id totleTradeId, '流程中' validStatusText, '01' validStatus, total.WORKFLOW_ID workflowId, null matchStatus, DATE_FORMAT(total.trade_date, '%Y-%m-%d') tradeDateText, mcp.counter_name counterId, total.counter_trader counterTrader, if(total.ps='T01','买入',if(total.ps='T02','卖出', null)) ps, total.ccy, fin_product.finprod_market_id finprodId, fin_product.finprod_abbr finprodName, total.unit_cprice unitCprice, total.unit_int unitInt, total.yield * 100 yield, total.exer_yield * 100 exerYield, total.share_amt/100 shareAmt, if(DATE_FORMAT(total.SETTLE_SPEED)='0','T+0', if(DATE_FORMAT(total.SETTLE_SPEED)='1','T+1')) settleSpeedText, data2.item_value deliveryType, data3.item_value clearType, DATE_FORMAT(total.eff_time, 'HH24:mi') effTimeText, total.remark, data1.item_value registOrg, ssai.sec_acct_id secAcctId, ssai.sec_acct_name secAcctName, sci.busi_acct_no acctNo, sci.acct_name acctName, sci.bank_dep acctBankDep, sci.large_payno acctBankDepoPayno
from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total left join MST_COUNTER_PARTY mcp on total.counter_id = mcp.counter_id left join fin_product on total.finprod_id = fin_product.finprod_id and total.finprod_type2 = fin_product.finprod_type2 left join STL_SEC_ACCT_INFO ssai on total.sec_manage_acct_id = ssai.sec_acct_id left join sys_datadict_list data1 on data1.item_code = ssai.REGIST_ORG and data1.dict_code = 'REGIST_ORG' left join sys_datadict_list data2 on data2.item_code = total.delivery_type and data2.dict_code = 'SETT_MODE' left join sys_datadict_list data3 on data3.item_code = total.clear_type and data3.dict_code = 'CLEAR_TYPE' left join STL_CAPACCT_INFO sci on ssai.trd_acct_id = sci.acct_no and ssai.trd_acct_ccy = sci.ccy where total.finprod_type2 = 'F01' and total.is_cancel != 'Y' and total.trade_status = '01' and exists (select 1 from WFL_TRD_PRODUCT_DEAL_PRE, WFL_TRD_PRODUCT_DEAL_ADD_PRE where WFL_TRD_PRODUCT_DEAL_PRE.TRADE_ID = WFL_TRD_PRODUCT_DEAL_ADD_PRE.TRADE_ID and WFL_TRD_PRODUCT_DEAL_PRE.TOTLE_TRADE_ID = total.totle_trade_id and WFL_TRD_PRODUCT_DEAL_ADD_PRE.Portfolio_Id in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where PTL_PORTFOLIO_AUTHORITY.USER_ID = #{loginUserName}))
AND total.TRADE_DATE = STR_TO_DATE(#{tradeDate}, '%Y-%m-%d')
AND total.ps = #{ps}
AND total.counter_id = #{counterId}
AND total.counter_trader like CONCAT_WS('', '%', #{counterTrader}, '%')
AND fin_product.FINPROD_MARKET_ID = #{finprodId}
AND total.SETTLE_SPEED = #{settleSpreed}
AND sci.busi_acct_no = #{accountId}
AND ssai.regist_org = #{registOrg}
AND total.sec_manage_acct_id = #{secAcctId}

union all select total.totle_trade_id totleTradeId, if(total.trade_status='01','有效', if(total.trade_status='03','撤销', null)) validStatusText, if(total.trade_status='01','02', if(total.trade_status='03','03', null)) validStatus, null workflowId, if(total.trade_status='03',null, if(TRD_MATCH_INFO.SEQNO=null,'待匹配','已匹配')) matchStatus, DATE_FORMAT(total.trade_date, '%Y-%m-%d') tradeDateText, mcp.counter_name counterId, total.counter_trader counterTrader, if(total.ps='T01','买入', if(total.ps='T02','卖出', null)) ps, total.ccy, fin_product.finprod_market_id finprodId, fin_product.finprod_abbr finprodName, total.unit_cprice unitCprice, total.unit_int unitInt, total.yield*100 yield, total.exer_yield*100 exerYield, total.share_amt/100 shareAmt, if(DATE_FORMAT(total.SETTLE_SPEED)='0','T+0', if(DATE_FORMAT(total.SETTLE_SPEED)='1','T+1', null)) settleSpeedText, data2.item_value deliveryType, data3.item_value clearType, DATE_FORMAT(total.eff_time, 'HH24:mi') effTimeText, total.remark, data1.item_value registOrg, ssai.sec_acct_id secAcctId, ssai.sec_acct_name secAcctName, sci.busi_acct_no acctNo, sci.acct_name acctName, sci.bank_dep acctBankDep, sci.large_payno acctBankDepoPayno
from TRD_FIN_PRODUCT_DEAL_TOTAL total left join MST_COUNTER_PARTY mcp on total.counter_id = mcp.counter_id left join fin_product on total.finprod_id = fin_product.finprod_id and total.finprod_type2 = fin_product.finprod_type2 left join STL_SEC_ACCT_INFO ssai on total.sec_manage_acct_id = ssai.sec_acct_id left join sys_datadict_list data1 on data1.item_code = ssai.REGIST_ORG and data1.dict_code = 'REGIST_ORG' left join sys_datadict_list data2 on data2.item_code = total.delivery_type and data2.dict_code = 'SETT_MODE' left join sys_datadict_list data3 on data3.item_code = total.clear_type and data3.dict_code = 'CLEAR_TYPE' left join STL_CAPACCT_INFO sci on ssai.trd_acct_id = sci.acct_no and ssai.trd_acct_ccy = sci.ccy left join TRD_MATCH_INFO on total.totle_trade_id = TRD_MATCH_INFO.PRE_TRADE_ID where total.busi_type = 'TRD69' and total.is_cancel = 'N' and exists (select 1 from TRD_PRODUCT_DEAL_PRE, TRD_PRODUCT_DEAL_ADD_PRE where TRD_PRODUCT_DEAL_PRE.TRADE_ID = TRD_PRODUCT_DEAL_ADD_PRE.TRADE_ID and TRD_PRODUCT_DEAL_PRE.TOTLE_TRADE_ID = total.totle_trade_id and TRD_PRODUCT_DEAL_ADD_PRE.Portfolio_Id in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where PTL_PORTFOLIO_AUTHORITY.USER_ID = #{loginUserName}))
and total.trade_status = '01'
and total.trade_status = '03'
and total.trade_status in ('01','03')
AND total.TRADE_DATE = STR_TO_DATE(#{tradeDate}, '%Y-%m-%d')
AND total.ps = #{ps}
AND total.counter_id = #{counterId}
AND total.counter_trader like CONCAT_WS('', '%', #{counterTrader}, '%')
AND fin_product.FINPROD_MARKET_ID = #{finprodId}
AND total.SETTLE_SPEED = #{settleSpreed}
AND sci.busi_acct_no = #{accountId}
AND ssai.regist_org = #{registOrg}
AND total.sec_manage_acct_id = #{secAcctId}
